    Arial,
    Helvetica,
    sans-serif;
  position: absolute;
  z-index: 1000;
  background-color: #fff;
  border-radius: 4px;
  overflow: hidden;
  font-family: var(--yagr-tooltip-font-family);
  pointer-events: none;
}
.yagr-tooltip__item {
  white-space: nowrap;
  display: flex;
  flex-direction: row;
  justify-content: left;
  align-items: center;
}
.yagr-tooltip__item._active {
  font-weight: bold;
}
.yagr-tooltip_default {
  font-size: 12px;
  padding: 4px 12px;
