  margin-bottom: 4px;
}
.yagr-tooltip_default .__section:last-child {
  margin: 0;
}
.yagr-tooltip_default .__section_title {
  font-size: 14px;
  font-weight: bold;
  margin-bottom: 2px;
}
.yagr-tooltip_default .__section_scale {
  margin-bottom: 2px;
  background-color: #eee;
  padding: 2px;
}
.yagr-tooltip_default .yagr-tooltip__mark {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  margin-right: 8px;
  display: block;
}
.yagr-tooltip_pinned {
  pointer-events: all;
}
.yagr-tooltip_pinned ._tooltip-list {
  max-height: 320px;
}
.yagr-tooltip ._hidden-rows-number {
  white-space: nowrap;
}
.yagr-tooltip__idx {
  width: 25px;
  white-space: nowrap;
  max-width: 25px;
  overflow: hidden;
}
.yagr-tooltip__tf {
  margin-left: 4px;
}
.yagr-point {
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
  will-change: transform;
  z-index: 100;
}
.yagr-point span {
  border-radius: 50%;
  display: block;
  width: 100%;
  height: 100%;
  border: solid 1px #fff;
  box-shadow: 0 1px 1px -1px #fff;
}
.yagr-legend {
  padding: 8px 24px 12px;
  display: block;
  max-width: 100%;
  width: 100%;
}
.yagr-legend__top {
  padding: 8px 24px 0;
}
.yagr-legend__container {
  width: 100%;
  height: 100%;
  overflow: hidden;
}
.yagr-legend__items {
  display: flex;
  flex-flow: row wrap;
  align-items: baseline;
  padding-left: 16px;
}
.yagr-legend__item {
  cursor: pointer;

