import {chromium} from 'playwright';
const browser = await chromium.launch({args: ['--disable-gpu', '--no-zygote', '--disable-dev-shm-usage']});
const page = await browser.newPage({viewport: {width: 1000, height: 600}});
await page.goto('http://127.0.0.1:5173/verify.html');
await page.waitForFunction(() => window.__ready);
const pct = (a, p) => a.length ? [...a].sort((x, y) => x - y)[Math.min(a.length - 1, Math.floor(a.length * p))] : NaN;
const stat = (a) => ({n: a.length, p50: +pct(a, .5).toFixed(2), p95: +pct(a, .95).toFixed(2), max: +Math.max(...a).toFixed(2)});

const base = await page.evaluate(() => window.__diag());
console.log('baseline', JSON.stringify(base));

// A. mount in StrictMode: 43 200 points, 10 updates per second
await page.evaluate(() => window.__mount(100, 4320000, true));
await page.waitForSelector('.cpu-chart canvas');
await page.waitForTimeout(1200);
console.log('A after mount', JSON.stringify(await page.evaluate(() => window.__diag())));
await page.evaluate(() => { window.__timings(); window.__frames(); });
await page.waitForTimeout(5000);
const t = await page.evaluate(() => window.__timings());
const f = await page.evaluate(() => window.__frames());
console.log('A setSeries ms', JSON.stringify(stat(t)), ' frames', JSON.stringify(stat(f)), 'frames>50ms:', f.filter(x => x > 50).length);
console.log('points in chart:', await page.evaluate(() => document.querySelector('.cpu-chart').getAttribute('aria-label')));
await page.screenshot({path: '/tmp/pw/v-live.png'});

// D. theme switch must not re-create the canvas
await page.evaluate(() => { document.querySelector('.cpu-chart canvas').dataset.marker = 'same'; });
await page.evaluate(() => window.__setDark(true));
await page.waitForTimeout(600);
console.log('D canvas kept:', await page.evaluate(() => document.querySelector('.cpu-chart canvas').dataset.marker));
await page.screenshot({path: '/tmp/pw/v-dark.png'});

// C. hover pause
const box = await page.locator('.cpu-chart .u-over').boundingBox();
await page.mouse.move(box.x + box.width * 0.5, box.y + box.height * 0.5);
await page.evaluate(() => window.__timings());
await page.waitForTimeout(1500);
console.log('C paused badge:', await page.getByText('Обновление приостановлено').count(), 'setSeries while hovering:', (await page.evaluate(() => window.__timings())).length);
await page.mouse.move(5, 5);
await page.waitForTimeout(600);
console.log('C after leave: badge', await page.getByText('Обновление приостановлено').count(), 'setSeries calls:', (await page.evaluate(() => window.__timings())).length > 0);

// B. zoom: drag-select then wait for several live updates, zoom must persist
const box2 = await page.locator('.cpu-chart .u-over').boundingBox();
await page.mouse.move(box2.x + box2.width * 0.4, box2.y + box2.height * 0.5);
await page.mouse.down();
await page.mouse.move(box2.x + box2.width * 0.55, box2.y + box2.height * 0.5, {steps: 5});
await page.mouse.up();
await page.mouse.move(5, 5);
await page.waitForTimeout(300);
const axisBefore = await page.evaluate(() => document.querySelector('.cpu-chart canvas').toDataURL().length);
console.log('B reset button:', await page.getByText('Сбросить масштаб').count());
await page.screenshot({path: '/tmp/pw/v-zoom.png'});
await page.waitForTimeout(2000);
console.log('B after live updates, reset button still:', await page.getByText('Сбросить масштаб').count());
await page.screenshot({path: '/tmp/pw/v-zoom2.png'});
await page.getByText('Сбросить масштаб').click();
await page.waitForTimeout(300);
console.log('B after reset click, button:', await page.getByText('Сбросить масштаб').count());

// E. resize
const sz = async () => page.evaluate(() => { const c = document.querySelector('.cpu-chart canvas'); return [c.style.width || c.clientWidth, c.style.height || c.clientHeight, document.querySelector('.cpu-chart').clientWidth, document.querySelector('.cpu-chart').clientHeight]; });
console.log('E initial', await sz());
await page.evaluate(() => window.__setSize(500, 300));
await page.waitForTimeout(500);
console.log('E 500x300 ->', await sz());
await page.screenshot({path: '/tmp/pw/v-small.png'});
await page.evaluate(() => window.__setSize(960, 520));
await page.waitForTimeout(500);
console.log('E 960x520 ->', await sz());

// F. unmount right after a resize (pending debounced onResize) and check cleanup
await page.evaluate(() => window.__setSize(700, 350));
await page.waitForTimeout(20);
await page.evaluate(() => window.__unmount());
await page.waitForTimeout(800);
const after = await page.evaluate(() => window.__diag());
console.log('F after unmount', JSON.stringify(after));
const leaked = {};
for (const [k, v] of Object.entries(after.listeners)) { const d = v - (base.listeners[k] ?? 0); if (d) leaked[k] = d; }
console.log('F net listener delta vs baseline:', JSON.stringify(leaked));
const t2 = await page.evaluate(() => window.__timings());
await page.waitForTimeout(1500);
console.log('F setSeries after unmount:', (await page.evaluate(() => window.__timings())).length);
await browser.close();
EOF
