const browser = await chromium.launch({args: ['--disable-gpu', '--no-zygote', '--disable-dev-shm-usage']});
async function scenario(name, {step, win, hist, hoverMs, settleMs = 1200}) {
  const page = await browser.newPage({viewport: {width: 1000, height: 600}});
  await page.goto('http://127.0.0.1:5173/verify.html');
