    await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
    await page.waitForTimeout(hoverMs);
    await page.mouse.move(5, 5);
  }
  await page.waitForTimeout(settleMs);
  const shape = await page.evaluate(() => window.__shape());
