  const ok = shape && shape.cfgT === shape.cfgV && shape.uT === shape.cfgT && shape.uV === shape.cfgT && shape.mono && shape.cfgT <= cap && Math.abs(shape.last - shape.now) < 600;
  console.log(name.padEnd(34), 'cap', cap, JSON.stringify(shape), ok ? 'OK' : 'FAIL', diag.errors.length ? diag.errors : '');
  await page.close();
}
