await scenario('partial overflow (hist 95, hover1s)', {step: 100, win: 10000, hist: 95, hoverMs: 1000});
await scenario('replace-all (cap 30, hover 4s)', {step: 100, win: 3000, hist: 30, hoverMs: 4000});
await browser.close();
EOF
